from pathlib import Path
p=Path('work/archiostal_renderer.js');s=p.read_text(encoding='utf-8');s=s.replace('uniform float emissive;void main()', 'uniform float emissive,planet;void main()')
s=s.replace('c=mix(c,color,emissive);gl_FragColor', '''c=mix(c,color,emissive);if(planet>.5){vec3 n=normalize(N);float terrain=sin(n.x*9.+sin(n.y*11.)*1.7)+sin(n.z*13.+n.y*7.)*.55+sin(n.x*31.+n.y*29.)*.12;float cloud=sin(n.x*38.+sin(n.z*18.)*3.)*sin(n.y*32.+n.z*17.);float sunlight=.35+.65*max(0.,dot(n,normalize(vec3(-.6,.7,-.5))));c=planet<1.5?mix(vec3(.035,.18,.29),vec3(.20,.39,.26),smoothstep(.12,.42,terrain)):mix(vec3(.34,.38,.41),vec3(.64,.65,.61),smoothstep(-.6,.7,terrain));if(planet<1.5)c=mix(c,vec3(.8,.85,.85),smoothstep(.42,.8,cloud)*.65);float rim=pow(1.-abs(n.z),3.);c=c*sunlight+vec3(.13,.3,.40)*rim;}gl_FragColor''')
s=s.replace("emissive:gl.getUniformLocation(program,'emissive')", "emissive:gl.getUniformLocation(program,'emissive'),planet:gl.getUniformLocation(program,'planet')")
s=s.replace('function draw(p,root=M.I(),glow=0){', 'function draw(p,root=M.I(),glow=0,planet=0){').replace('gl.uniform1f(L.emissive,glow);gl.drawElements', 'gl.uniform1f(L.emissive,glow);gl.uniform1f(L.planet,planet);gl.drawElements')
s=s.replace('for(const p of vista)draw(p,M.I(),.3);', 'for(const [i,p]of vista.entries())draw(p,M.I(),.3,i+1);')
s=s.replace("gl.uniform1f(L.emissive,1);gl.drawArrays(gl.POINTS", "gl.uniform1f(L.emissive,1);gl.uniform1f(L.planet,0);gl.drawArrays(gl.POINTS")
p.write_text(s,encoding='utf-8')
